# Our toy corpus: each word is a tuple of symbols + a frequency.
# '</w>' marks end-of-word (so "low" in "lower" and "low" alone are distinguishable).

corpus = {
    ("l", "o", "w", "</w>"): 5,
    ("l", "o", "w", "e", "r", "</w>"): 2,
    ("n", "e", "w", "e", "s", "t", "</w>"): 6,
    ("w", "i", "d", "e", "s", "t", "</w>"): 3,
}

for word, freq in corpus.items():
    print(f"{' '.join(word):<22} x{freq}")

from collections import Counter

def get_pair_counts(corpus):
    """Count how often each ADJACENT symbol pair occurs, weighted by word frequency."""
    pairs = Counter()
    for word, freq in corpus.items():
        for i in range(len(word) - 1):
            pairs[(word[i], word[i + 1])] += freq
    return pairs

pairs = get_pair_counts(corpus)
print("top 5 pairs:", pairs.most_common(5))

def merge_pair(corpus, pair):
    """Merge every occurrence of `pair` = (a, b) into a single symbol 'ab'."""
    a, b = pair
    new_corpus = {}
    for word, freq in corpus.items():
        new_word, i = [], 0
        while i < len(word):
            if i < len(word) - 1 and word[i] == a and word[i + 1] == b:
                new_word.append(a + b)      # merge!
                i += 2
            else:
                new_word.append(word[i])
                i += 1
        new_corpus[tuple(new_word)] = freq
    return new_corpus

# quick check: merge ('e','s') once
demo = merge_pair(corpus, ("e", "s"))
for word, freq in demo.items():
    print(f"{' '.join(word):<22} x{freq}")

